export function templateContentRule(
  templateId: string,
  standard?: { id: string; content: TemplateContentRule },
): TemplateContentRule {
  if (standard) {
    if (standard.id !== templateId) throw new Error("模板快照与类型不一致");
    return standard.content;
  }
  if (!Object.hasOwn(TEMPLATE_CONTENT_SPEC, templateId))
    throw new Error(
      "Unsupported practice or activity type; use the published LearnWeave catalog.",
    );
  return TEMPLATE_CONTENT_SPEC[
    templateId as keyof typeof TEMPLATE_CONTENT_SPEC
  ];
}

/** Shared semantic constraints, independent of either host's native document storage. */
export function choiceIssue(
  rule: {
    choice?: Pick<
      NonNullable<TemplateContentRule["choice"]>,
      "minOptions" | "maxOptions" | "answerCount"
    >;
  },
  options?: { value: string; imageSrc?: string }[],
  answers?: string[],
) {
  const q = rule.choice;
  if (!q) return undefined;
  if (
    !options ||
    options.length < q.minOptions ||
    options.length > q.maxOptions ||
    new Set(options.map((o) => o.value)).size !== options.length ||
    !answers ||
    answers.length !== q.answerCount ||
    new Set(answers).size !== answers.length ||
    answers.some((answer) => !options.some((o) => o.value === answer))
  )
    return `invalid question or answer: supply ${q.minOptions}–${q.maxOptions} unique options and ${q.answerCount} matching answer`;
}

/** Native DSL shape remains a host check; this is the common supported quiz subset. */
export function quizContentIssue(
  questions: readonly BindingQuestion[],
  choice: TemplateContentRule["choice"] = undefined,
) {
  if (
    !questions.length ||
    questions.length >
      (choice?.questionCount ?? SINGLE_CHOICE_STANDARD.maxQuestions)
  )
    return "invalid question count";
  const ids = new Set<string>();
  for (const q of questions) {
    if (
      q.type !==
        (choice?.questionType ?? SINGLE_CHOICE_STANDARD.questionType) ||
      !q.id ||
      ids.has(q.id) ||
      !q.question?.trim() ||
      q.question.length > SINGLE_CHOICE_STANDARD.maxQuestionLength
    )
      return "invalid question type, ID or text";
    ids.add(q.id);
    const issue = choiceIssue(
      { choice: choice ?? SINGLE_CHOICE_STANDARD },
      q.options,
      q.answer,
    );
    if (issue) return issue;
    if (
      q.options?.some(
        (o) =>
          !o.value ||
          o.value.length > SINGLE_CHOICE_STANDARD.maxOptionValueLength ||
          !o.label?.trim() ||
          o.label.length > SINGLE_CHOICE_STANDARD.maxOptionLabelLength,
      )
    )
      return "invalid question option value or label";
  }
}

export function productionInputIssue(
  rule: TemplateContentRule,
  input: {
    contentRef?: string;
    audioSrc?: string;
    promptText?: string;
    imageSrc?: string;
    options?: { value: string; label?: string; imageSrc?: string }[];
    answer?: string;
  },
  resolvedMedia = false,
) {
  if (rule.builder === "existing-slide")
    return input.contentRef
      ? undefined
      : "Existing-slide builder requires contentRef";
  if (rule.choice) {
    const issue = quizContentIssue(
      [
        {
          id: "q1",
          type: rule.choice.questionType,
          question: rule.choice.prompt,
          options: input.options,
          answer: input.answer === undefined ? undefined : [input.answer],
        },
      ],
      rule.choice,
    );
    if (issue) return issue;
  }
  if (
    rule.choice?.stimulus === "audio" &&
    !input.audioSrc &&
    (resolvedMedia || !input.promptText)
  )
    return "Audio stimulus requires saved audio or promptText for synthesis";
  if (rule.choice?.stimulus === "image" && !input.imageSrc)
    return "Image stimulus requires a stem image";
  if (
    rule.choice?.options === "image" &&
    input.options?.some((o) => !o.imageSrc)
  )
    return "Each image option requires a saved image";
}

export function boundAssets(activity: BindingActivity) {
  return templateContentRule(
    activity.templateId,
    activity.standard,
  ).bindings.flatMap((binding) => {
    const value = activity[binding.field];
    const ids = binding.many
      ? Object.values(typeof value === "object" ? value : {})
      : [typeof value === "string" ? value : undefined];
    return ids.map((id) => ({
      id,
      kind: binding.kind,
      field: binding.field,
    }));
  });
}

export function templateBindingIssue(
  activity: BindingActivity,
  view: {
    elements: readonly { id: string; type: string }[];
    questions?: readonly BindingQuestion[];
  },
) {
  const rule = templateContentRule(activity.templateId, activity.standard);
  for (const field of rule.forbiddenBindings || []) {
    if (activity[field as keyof BindingActivity] !== undefined)
      return `forbidden binding: ${field}`;
  }
  if (rule.choice) {
    const questions = view.questions;
    if (!questions || questions.length !== rule.choice.questionCount)
      return "quiz missing or question count invalid";
    const q = questions.find((q) => q.id === activity.questionId);
    if (!q || q.type !== rule.choice.questionType)
      return "invalid question or answer";
    const contentIssue = quizContentIssue(questions, rule.choice);
    if (contentIssue) return contentIssue;
    for (const binding of rule.bindings.filter((b) => b.many)) {
      const mapping = activity[binding.field];
      if (
        !mapping ||
        typeof mapping !== "object" ||
        Object.keys(mapping).length !== q.options!.length ||
        new Set(Object.values(mapping)).size !== q.options!.length ||
        q.options!.some((o) => !Object.hasOwn(mapping, o.value))
      )
        return `${binding.field}: option binding missing or duplicated`;
    }
  }
  for (const binding of boundAssets(activity)) {
    if (
      !binding.id ||
      !view.elements.some((e) => e.id === binding.id && e.type === binding.kind)
    )
      return `${binding.field}: ${binding.kind} binding missing`;
  }
}
